"""Authored course data. Run from any directory; stable IDs preserve progress."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
existing=json.loads((root/'content/lessons.json').read_text())
old=[next(l for l in existing if l['id']==id) for id in ['fractions','equations','functions','matrix']]
modules=[]
def add(id,title,subject,qs,source,prereq,explain,example,error,card,tasks,theory):
 modules.append(dict(id=id,title=title,subject=subject,examQuestions=qs,sourceId=source,requires=prereq,explain=explain,example=example,error=error,card=card,tasks=tasks,theory=theory))
B='Основа';M='Матанализ';L='Линейная алгебра'
add('powers','Степени, корни и ограничения',B,[],'edb52f3eef6d','functions',
'Степень — короткая запись умножения: $2^3 = 8$. Нулевая степень ненулевого числа равна 1; отрицательная означает обратное число: $2^{-2} = 1/4$. Корень квадратный — неотрицательное число, квадрат которого даёт подкоренное выражение. Поэтому $√9 = 3$, хотя уравнение $x^2 = 9$ имеет два корня.',
'Вычислим $3^2 × 3^{-1}$. При умножении степеней с одинаковым основанием показатели складываются: $3^{2-1} = 3$. Для корня сначала проверь область: выражение под квадратным корнем должно быть неотрицательным.',
'Корень из квадрата числа равен его модулю: $√{x^2} = |x|$. При отрицательном x нельзя просто убрать корень.',
['Чему равен квадратный корень из квадрата действительного числа?','Модулю этого числа: корень по определению неотрицателен.'],
[['Вычисли $2^3 × 2^{-1}$.',4,'Показатель: 3 − 1 = 2; 2² = 4.'],['Вычисли $5^0$.',1,'Основание ненулевое, нулевая степень равна 1.'],['Вычисли $√{(-7)^2}$.',7,'Квадрат равен 49, неотрицательный корень — 7.'],['Вычисли $4^{-1}$.',.25,'Это 1/4.']],
['Степенные правила действуют с учётом области определения. Для произвольных действительных показателей обычно берут положительное основание.','Перед упрощением дроби исключи нули знаменателя; перед квадратным корнем потребуй неотрицательное подкоренное выражение. Эти ограничения сохраняются после сокращения.'])
add('logarithms','Логарифм: восстановить показатель',B,[],'edb52f3eef6d','powers',
'Логарифм отвечает: в какую степень возвести основание, чтобы получить число? $log_2 8 = 3$, потому что $2^3 = 8$. Основание положительно и не равно 1; аргумент строго положителен. Натуральный логарифм ln имеет основание e, примерно 2,718.',
'Решим $log_2 x = 4$. Перейдём к степени: $x = 2^4 = 16$. Проверка области: 16 > 0. Логарифм произведения равен сумме логарифмов, но логарифм суммы такого правила не имеет.',
'Нельзя писать ln(a + b) = ln(a) + ln(b). Последняя сумма равна ln(ab) для положительных a и b.',
['Как перевести логарифмическое равенство в показательное?','log с основанием a от b равен c означает, что a в степени c равно b.'],
[['Найди $log_3 27$.',3,'3³ = 27.'],['Найди $log_5 1$.',0,'5⁰ = 1.'],['Реши $log_2 x = 5$: найди x.',32,'x = 2⁵ = 32.'],['Найди $log_2 (1/4)$.',-2,'2⁻² = 1/4.']],
['Для положительных u,v: ln(uv)=ln u+ln v, ln(u/v)=ln u−ln v. Для u>0: ln(u^r)=r ln u.','Показательная функция с основанием больше 1 возрастает; при основании между 0 и 1 убывает. Её обратная функция — логарифм.'])
add('trigonometry','Тригонометрия: окружность вместо зубрёжки',B,[],'edb52f3eef6d','powers',
'На единичной окружности cos угла — горизонтальная координата, sin — вертикальная. Радианы измеряют длину дуги единичной окружности: половина оборота — π. Основное тождество: $sin^2 x + cos^2 x = 1$. Тангенс — отношение sin к cos там, где cos не равен нулю.',
'При угле 0 точка окружности (1, 0), поэтому cos 0 = 1, sin 0 = 0. После четверти оборота (π/2) точка (0, 1): cos = 0, sin = 1. После половины оборота точка (−1, 0).',
'Производные и замечательные пределы используют радианы. Подставлять градусы в них без перевода нельзя.',
['Что означают sin и cos на единичной окружности?','sin — вертикальная координата точки, cos — горизонтальная.'],
[['Найди sin(0).',0,'Начальная точка (1, 0).'],['Найди cos(π).',-1,'Половина оборота приводит в (−1, 0).'],['Найди sin(π/2).',1,'Четверть оборота: (0, 1).'],['Вычисли sin²(0,7) + cos²(0,7).',1,'Основное тождество верно для любого действительного угла.']],
['sin нечётная функция, cos чётная. Период обеих — 2π, период tan — π.','sin(a+b)=sin a cos b+cos a sin b; cos(a+b)=cos a cos b−sin a sin b. Из этих формул получаются формулы двойного угла.'])
add('sets','Множества, окрестности и грани',M,[1,2,3],'edb52f3eef6d','functions',
'Множество — набор объектов. Объединение собирает всё из двух наборов, пересечение оставляет общие элементы. Окрестность точки — все точки ближе заданного положительного расстояния. На прямой это открытый интервал. Верхняя грань ограничивает множество сверху; точная верхняя грань — наименьшая из таких границ.',
'У множеств {1, 2, 3} и {2, 3, 4} пересечение {2, 3}, объединение {1, 2, 3, 4}. У интервала (0, 1) точная верхняя грань равна 1, но максимума нет: сама единица не входит.',
'Супремум не обязан принадлежать множеству. Максимум, если существует, принадлежит.',
['Чем супремум отличается от максимума?','Супремум — наименьшая верхняя граница; максимум дополнительно принадлежит множеству.'],
[['Сколько элементов в пересечении {1,2,3} и {3,4}?',1,'Общий элемент только 3.'],['Каков супремум интервала (−2, 5)?',5,'Числа подходят к 5 слева; меньшая верхняя граница невозможна.'],['Каков инфимум [−3, 7)?',-3,'−3 — наибольшая нижняя граница.'],['Сколько элементов в объединении {1,2} и {2,3}?',3,'Получаем {1,2,3}; дубликат не считается.']],
['Метрика d(x,y) — неотрицательное расстояние: равно нулю только при x=y, симметрично и удовлетворяет неравенству треугольника. В Rⁿ евклидово расстояние — корень суммы квадратов разностей координат.','Открытое множество содержит некоторую окрестность каждой своей точки. Замкнутое содержит все свои предельные точки. Область — открытое связное множество. Односвязность означает возможность стянуть каждую замкнутую петлю в точку внутри области.','Полнота действительных чисел: непустое ограниченное сверху множество имеет супремум. Для вложенных непустых замкнутых ограниченных отрезков пересечение непусто; если длины стремятся к нулю, общая точка единственна. Идея доказательства: взять супремум левых концов и сравнить с каждым правым.'])
add('induction','Индукция и бином Ньютона',M,[4],'edb52f3eef6d','powers',
'Математическая индукция доказывает утверждение для всех натуральных номеров. Сначала база: первый номер. Затем переход: из верности для k выводится верность для k+1. Одной проверки нескольких чисел недостаточно.',
'Сумма первых n натуральных чисел равна n(n+1)/2. База n=1 верна. Предположим формулу для k, добавим k+1: k(k+1)/2+(k+1)=(k+1)(k+2)/2. Получилась нужная формула для следующего номера.',
'В переходе нельзя предполагать верным то, что требуется доказать для k+1.',
['Какие два обязательных шага есть у индукции?','База и переход от произвольного k к k+1.'],
[['Чему равна сумма 1+2+3+4+5?',15,'5×6/2 = 15.'],['Чему равен коэффициент при x в (1+x)³?',3,'Разложение: 1+3x+3x²+x³.'],['Чему равна сумма чисел от 1 до 10?',55,'Формула суммы первых n чисел: n(n+1)/2. При n=10 получаем 10×11/2=55.'],['Чему равен коэффициент при x² в (1+x)⁴?',6,'Число сочетаний из 4 по 2: 4×3/2.']],
['Неравенство Бернулли: (1+x)ⁿ ≥ 1+nx при целом n≥1 и x≥−1. Индукционный переход получается умножением на неотрицательное 1+x и добавлением неотрицательного nx².','Бином Ньютона: (a+b)ⁿ — сумма C(n,k)a^(n−k)b^k по k от 0 до n; C(n,k)=n!/(k!(n−k)!). Неравенство Коши для неотрицательных чисел: среднее арифметическое не меньше среднего геометрического.'])
add('sequences','Последовательности и предел',M,[6,7,8,9],'e7ba02c196d3','powers',
'Последовательность — числа, пронумерованные натуральными индексами. Предел A означает: начиная с некоторого номера все члены находятся как угодно близко к A. Конечное число первых членов на предел не влияет.',
'У последовательности aₙ = 3 + 1/n предел равен 3. Чтобы расстояние до 3 стало меньше 0,01, достаточно n > 100. Можно подобрать номер для любой положительной точности.',
'Ограниченность не гарантирует сходимость: (−1)ⁿ ограничена, но колеблется между двумя значениями.',
['Что нужно проверить в определении предела последовательности?','Для каждой положительной точности существует номер, после которого все члены ближе этой точности к пределу.'],
[['Найди предел 5 + 1/n при n → ∞.',5,'1/n стремится к нулю.'],['Найди предел (2n+1)/n.',2,'Разделим: 2+1/n.'],['Найди предел 7−3/n.',7,'3/n стремится к нулю.'],['Найди предел (4n+2)/(2n+1).',2,'Числитель в точности вдвое больше знаменателя.']],
['Сходящаяся последовательность ограничена. Доказательство: хвост лежит в окрестности предела радиуса 1, конечное начало ограничено максимумом модулей. Предел единственен: для двух разных пределов взять непересекающиеся малые окрестности.','Теорема Больцано–Вейерштрасса: из ограниченной действительной последовательности можно выделить сходящуюся подпоследовательность. Идея — вложенные половины отрезка, содержащие бесконечно много членов.','Монотонная ограниченная последовательность сходится. Для возрастающей предел равен супремуму множества её значений. Число e определяется как предел (1+1/n)ⁿ; существование следует из монотонности и ограниченности. Если две подпоследовательности имеют разные пределы, исходная последовательность не сходится.'])
add('limits','Предел функции: подойти, не подставить',M,[10,11,12,13],'e7ba02c196d3','functions',
'Предел функции в точке описывает значения рядом с точкой, а не обязательно в самой точке. Запись x → a означает приближение аргумента к a. При поиске предела сначала пробуют подстановку; если получается 0/0, требуется преобразование.',
'Найдём предел (x²−4)/(x−2) при x → 2. Подстановка даёт 0/0. Разложим x²−4=(x−2)(x+2). При x≠2 можно сократить x−2. Остаётся x+2, предел равен 4.',
'0/0 — неопределённость, а не число 0 или 1. Сокращение законно только вне точки, но для предела этого достаточно.',
['Почему значение функции в точке не определяет её предел?','Предел зависит от значений в проколотой окрестности, то есть рядом с точкой.'],
[['Предел (x²−9)/(x−3) при x → 3.',6,'Сокращение даёт x+3; результат 6.'],['Предел (x²−16)/(x−4) при x → 4.',8,'Разность квадратов даёт x+4.'],['Предел (x²−1)/(x−1) при x → 1.',2,'После сокращения остаётся x+1.'],['Предел (x²−25)/(x−5) при x → 5.',10,'После сокращения остаётся x+5.']],
['По Коши: для любого ε>0 существует δ>0, такое что из 0<|x−a|<δ следует |f(x)−A|<ε. По Гейне: вдоль любой последовательности допустимых xₙ≠a, стремящейся к a, значения f(xₙ) стремятся к A. Эквивалентность доказывается в одну сторону определением, в другую — выбором контрпоследовательности.','Двусторонний предел существует тогда и только тогда, когда оба односторонних существуют и равны. Функция с конечным пределом ограничена в некоторой проколотой окрестности; ненулевой предел сохраняет свой знак поблизости.','Бесконечно малая функция стремится к нулю. f стремится к A тогда и только тогда, когда f=A+α, где α бесконечно малая. Обратная к ненулевой бесконечно малой — бесконечно большая по модулю.','Для конечных пределов работают сумма и произведение; деление требует ненулевого предела знаменателя. Теорема о трёх функциях: если нижняя и верхняя оценки стремятся к одному A, зажатая между ними функция тоже стремится к A.'])
add('equivalents','Замечательные пределы и эквивалентности',M,[14,15],'e7ba02c196d3','trigonometry',
'При малом радианном угле sin x почти равен x: отношение sin x к x стремится к 1. Эквивалентные бесконечно малые имеют отношение, стремящееся к 1. В произведениях и дробях это часто позволяет заменить сложное простым.',
'Предел sin(3x)/x при x → 0: умножим и разделим на 3. Получим 3·sin(3x)/(3x). Отношение стремится к 1, ответ 3.',
'Не заменяй слагаемые эквивалентными внутри разности автоматически: главные части могут сократиться.',
['Где обычно можно заменять бесконечно малые эквивалентными?','В произведениях и отношениях, при выполнении условий; в суммах и разностях нужна отдельная проверка.'],
[['Предел sin(5x)/x при x → 0.',5,'Выделим sin(5x)/(5x), его предел 1.'],['Предел ln(1+2x)/x при x → 0.',2,'ln(1+u) эквивалентен u.'],['Предел sin(4x)/sin(2x) при x → 0.',2,'Отношение главных частей 4x/(2x).'],['Предел (1−cos x)/x² при x → 0.',.5,'1−cos x эквивалентен x²/2.']],
['Первый замечательный предел sin x/x → 1 при x→0. Геометрическое доказательство использует sin x < x < tan x для малых положительных x и теорему о зажатой функции.','Второй замечательный предел (1+x)^(1/x) → e при x→0, 1+x>0. Следствия: ln(1+x) ~ x, e^x−1 ~ x, (1+x)^α−1 ~ αx для α≠0. Также tan x ~ x и 1−cos x ~ x²/2.'])
add('continuity','Непрерывность и разрывы',M,[5,16,17,18,19,20,21,22,23],'e7ba02c196d3','limits',
'Функция непрерывна в точке, если её значение существует и совпадает с пределом. Практически: подставление аргумента согласовано с приближением. Устранимый разрыв можно исправить одним значением; скачок нельзя исправить изменением одной точки.',
'Функция (x²−1)/(x−1) не определена при x=1. Её предел там равен 2. Если отдельно положить f(1)=2, получится непрерывная функция. При другом значении останется устранимый разрыв.',
'Нельзя применять теорему о максимуме на отрезке к открытому интервалу без дополнительных условий.',
['Когда разрыв можно устранить одним значением?','Когда существует конечный предел: значение в точке нужно положить равным этому пределу.'],
[['Как задать f(2), чтобы (x²−4)/(x−2) стала непрерывной?',4,'Предел равен 2+2.'],['Минимум x² на [−1,2].',0,'Ноль достигается при x=0.'],['Максимум x² на [−1,2].',4,'Сравни 0, значения на концах 1 и 4.'],['Как задать f(3) для непрерывности (x²−9)/(x−3)?',6,'После сокращения x+3.']],
['Для монотонности сравнивают значения при x₁<x₂. Чётность: f(−x)=f(x), нечётность: f(−x)=−f(x), область должна быть симметрична. Период T≠0 удовлетворяет f(x+T)=f(x). Скалярная функция возвращает число, вектор-функция — вектор.','Разрыв первого рода: конечные односторонние пределы существуют; если они разные, это скачок, если равны — устранимый разрыв. Если хотя бы один односторонний предел не конечен или не существует, разрыв второго рода.','Непрерывная на отрезке функция ограничена и достигает максимума и минимума (Вейерштрасс). Она принимает все промежуточные значения (Больцано–Коши); разные знаки на концах обеспечивают хотя бы один нуль внутри. Доказательства опираются на полноту действительных чисел.','Равномерная непрерывность: одна δ подходит всем точкам области для выбранной ε. Теорема Кантора: непрерывность на компактном отрезке даёт равномерную непрерывность. Кусочная непрерывность допускает конечное число разрывов первого рода на рассматриваемом отрезке.','Сложная функция — применение правил последовательно; непрерывные функции можно компоновать. Строго монотонная непрерывная функция на промежутке имеет непрерывную обратную на своём образе; её график зеркален относительно y=x.','arcsin, arccos, arctan — обратные к sin, cos, tan на выбранных промежутках монотонности. Гиперболические функции: sh x=(e^x−e^(−x))/2, ch x=(e^x+e^(−x))/2, th x=sh x/ch x; ch²x−sh²x=1. Обратные гиперболические функции определяются обращением на промежутках монотонности.'])
add('derivative','Производная: скорость изменения',M,[24,25,26],'621f12ef7570','limits',
'Производная показывает мгновенную скорость изменения функции. Берём изменение выхода, делим на изменение входа и устремляем шаг к нулю. Геометрически это наклон касательной. Для x² производная равна 2x.',
'Для f(x)=x² при x=3: ((3+h)²−9)/h = (6h+h²)/h = 6+h. При h → 0 получаем 6. Касательная в точке (3,9): y=9+6(x−3).',
'Производная в точке — число; производная как функция зависит от аргумента.',
['Что показывает производная геометрически?','Угловой коэффициент касательной к графику, когда конечная производная существует.'],
[['Производная x² в точке 4.',8,'2x при x=4 равно 8.'],['Производная 3x+7 в любой точке.',3,'Наклон прямой постоянен.'],['Производная x³ в точке 2.',12,'3x² при x=2 равно 12.'],['Производная постоянной 8.',0,'Постоянная не меняется.']],
['Определение: f′(a)=lim(h→0)(f(a+h)−f(a))/h. Дифференцируемость означает приращение f(a+h)−f(a)=Ah+o(h); коэффициент A равен производной. Дифференцируемость влечёт непрерывность, но не наоборот: |x| непрерывна и не дифференцируема в нуле.','Таблица: (x^α)′=αx^(α−1) на области допустимости, (e^x)′=e^x, (ln x)′=1/x при x>0, (sin x)′=cos x, (cos x)′=−sin x.','Касательная: y=f(a)+f′(a)(x−a). Если f′(a)≠0, наклон нормали равен −1/f′(a). При горизонтальной касательной нормаль вертикальна.'])
add('derivative-rules','Произведение, частное и цепочка',M,[27,28],'621f12ef7570','derivative',
'Сумма дифференцируется по частям. Для произведения нужно два слагаемых: (uv)′=u′v+uv′. Для сложной функции сначала производная внешней по её аргументу, затем умножение на производную внутренней.',
'Найдём производную (2x+1)³ при x=1. Внешнее правило даёт 3(2x+1)², внутренняя производная равна 2. Итого 6(2x+1)², в точке 1 это 54.',
'Производная произведения не равна произведению производных. В цепочке нельзя потерять внутреннюю производную.',
['Как дифференцировать сложную функцию?','Производную внешней функции умножить на производную внутренней, сохранив внутренний аргумент.'],
[['Производная (3x+1)² при x=1.',24,'2(3x+1)×3 = 24.'],['Производная x·x² при x=2.',12,'Это x³; производная 3x².'],['Производная (2x−1)³ при x=1.',6,'3(2x−1)²×2 = 6.'],['Производная 1/x при x=2.',-.25,'−1/x² = −1/4.']],
['Правило частного: (u/v)′=(u′v−uv′)/v², где v≠0. Все функции должны быть дифференцируемы в рассматриваемой точке.','Логарифмическое дифференцирование полезно для произведений и переменных степеней. Для положительной y сначала записывают ln y, затем y′/y. Пример: y=x^x при x>0, ln y=x ln x, y′=x^x(ln x+1).'])
add('implicit','Неявная и параметрическая производная',M,[29,30],'621f12ef7570','derivative-rules',
'Иногда y не выражена через x: например x²+y²=25. Тогда дифференцируем равенство, считая y функцией x. Производная y² равна 2y·y′. После этого решаем уравнение относительно y′.',
'Для окружности x²+y²=25 получаем 2x+2yy′=0. При y≠0: y′=−x/y. В точке (3,4) наклон равен −3/4.',
'В точке с y=0 эта формула делит на ноль. Там нельзя объявлять конечную производную по этой записи.',
['Почему при дифференцировании y² появляется y′?','y зависит от x, поэтому применяется правило сложной функции.'],
[['Наклон x²+y²=25 в точке (4,3).',-4/3,'y′=−x/y=−4/3.'],['Если x=t², y=t³, найди dy/dx при t=2.',3,'(dy/dt)/(dx/dt)=3t²/(2t)=3.'],['Наклон x²+y²=25 в точке (0,5).',0,'−0/5=0.'],['Если x=2t, y=t², найди dy/dx при t=3.',3,'2t/2=t.']],
['Для F(x,y)=0 при непрерывных частных производных и F_y≠0 локально можно выразить y(x), и y′=−F_x/F_y.','Для параметров x=x(t), y=y(t): dy/dx=y′(t)/x′(t) при x′(t)≠0. Для обратной функции: (f⁻¹)′(f(a))=1/f′(a), если производная f непрерывна в окрестности и f′(a)≠0.'])
add('differential','Дифференциал и линейное приближение',M,[31,32,35],'621f12ef7570','derivative-rules',
'Дифференциал — линейная главная часть изменения функции: dy=f′(x)dx. При малом шаге dx он приближает настоящее изменение. Вторая производная — производная от первой, а не её квадрат.',
'Приблизим (3,01)². В точке 3 значение 9, производная 6, шаг 0,01. Линейное приближение: 9+6·0,01=9,06. Точное значение 9,0601, ошибка 0,0001.',
'Дифференциал не всегда совпадает с полным приращением. Отброшенная ошибка мала относительно шага.',
['Чем вторая производная отличается от квадрата первой?','Это повторное дифференцирование первой производной, а не умножение её на себя.'],
[['Вторая производная x³ при x=2.',12,'Первая 3x², вторая 6x.'],['Дифференциал x² при x=3 и dx=0,1.',.6,'2×3×0,1=0,6.'],['Третья производная x³.',6,'x³ → 3x² → 6x → 6.'],['Линейное приближение (2,01)² около 2.',4.04,'4+4×0,01=4,04.']],
['Дифференциал сохраняет форму dy=f′(x)dx при замене независимой переменной на дифференцируемую функцию: это следует из цепного правила. Для высших дифференциалов такой простой инвариантности нет без дополнительных слагаемых.','Формула Лейбница: n-я производная произведения uv — сумма C(n,k)u^(k)v^(n−k). При независимой x: dⁿy=f^(n)(x)(dx)ⁿ.'])
add('mean-value','Ролль, Лагранж и Лопиталь',M,[33,34],'621f12ef7570','derivative-rules',
'Теорема Лагранжа связывает среднюю скорость на отрезке с мгновенной: где-то внутри они равны. Условия важны: функция непрерывна на всём отрезке и дифференцируема внутри.',
'Для x² на [1,3] средний наклон (9−1)/(3−1)=4. Производная 2x равна 4 при x=2. Эта точка действительно внутри отрезка.',
'Лопиталь применяют к отношениям с неопределённостью 0/0 или ∞/∞ при выполнении условий, а не к любой дроби.',
['Какие условия нужны в теореме Лагранжа?','Непрерывность на замкнутом отрезке и дифференцируемость внутри него.'],
[['Точка Лагранжа для x² на [0,4].',2,'Средний наклон 4; 2x=4.'],['Предел (eˣ−1)/x при x → 0.',1,'0/0; отношение производных eˣ/1 → 1.'],['Точка Лагранжа для x² на [2,6].',4,'Средний наклон (36−4)/4=8; 2x=8.'],['Предел ln x/(x−1) при x → 1.',1,'0/0; (1/x)/1 → 1.']],
['Ролль: при условиях Лагранжа и равных значениях на концах найдётся внутренняя точка с нулевой производной. Доказательство: максимум и минимум достигаются; если функция не постоянна, один экстремум внутренний, и применима теорема Ферма.','Лагранж выводится из Ролля вычитанием секущей прямой. Коши: для двух функций с теми же условиями найдётся c, где (f(b)−f(a))g′(c)=(g(b)−g(a))f′(c).','Одна стандартная форма Лопиталя: f,g дифференцируемы в проколотой односторонней окрестности, g′≠0; имеется 0/0 или ∞/∞ и предел f′/g′ существует (конечный или бесконечный). Тогда исходное отношение имеет тот же предел. Если предел производных не существует, вывод о пределе исходного отношения из этого не следует.'])
add('taylor','Тейлор: заменить функцию многочленом',M,[36],'621f12ef7570','differential',
'Многочлен Тейлора подбирают так, чтобы совпадали значение функции и её первые производные в выбранной точке. Возле этой точки он приближает функцию. Коэффициенты: значение n-й производной, делённое на n! — произведение чисел от 1 до n.',
'У eˣ все производные в нуле равны 1. До квадратичного члена получаем 1+x+x²/2. При x=0,1 приближение равно 1,105. Это приближение, а не точное равенство для ненулевого x.',
'Нельзя забывать факториал или остаточный член, если требуется строгое равенство и оценка ошибки.',
['Зачем в формуле Тейлора нужен остаточный член?','Он выражает разность между функцией и многочленом и позволяет оценить точность.'],
[['Коэффициент при x² в многочлене Тейлора eˣ в нуле.',.5,'f″(0)/2! = 1/2.'],['Приближение e⁰·² по 1+x+x²/2.',1.22,'1+0,2+0,04/2=1,22.'],['Коэффициент при x² в разложении cos x в нуле.',-.5,'cos″(0)=−1; делим на 2.'],['Коэффициент при x³ в разложении eˣ в нуле.',1/6,'1/3! = 1/6.']],
['Форма Пеано: f(x)=Σ от k=0 до n f^(k)(a)(x−a)^k/k! + o((x−a)ⁿ), при достаточной дифференцируемости в точке.','Остаток Лагранжа: f^(n+1)(ξ)(x−a)^(n+1)/(n+1)! при соответствующей непрерывности на отрезке и дифференцируемости внутри. Остаток Коши: f^(n+1)(ξ)(x−ξ)ⁿ(x−a)/n!. Точка ξ между a и x.','Базовые разложения в нуле: sin x=x−x³/6+o(x³); cos x=1−x²/2+o(x²); ln(1+x)=x−x²/2+o(x²). Для вычисления предела оставляют столько членов, чтобы первое несократившееся слагаемое стало видно.'])
add('extrema','Экстремумы и исследование графика',M,[37,38,39,40],'621f12ef7570','derivative-rules',
'Производная помогает узнать направление изменения: положительная — функция возрастает на промежутке, отрицательная — убывает. Для локального максимума знак меняется с плюса на минус, для минимума — с минуса на плюс.',
'У f(x)=x²−4x производная 2x−4. Она равна нулю при x=2. Слева знак минус, справа плюс: это минимум. Значение f(2)=−4.',
'Нулевая производная сама по себе не гарантирует экстремума: у x³ в нуле производная нулевая, но функция продолжает возрастать.',
['Как по знаку производной распознать локальный минимум?','При переходе через точку знак производной меняется с минуса на плюс.'],
[['Абсцисса минимума x²−6x.',3,'2x−6=0, знак меняется с минуса на плюс.'],['Минимальное значение x²−4x.',-4,'Вершина при x=2, значение 4−8.'],['Абсцисса максимума −x²+8x.',4,'−2x+8=0, переход с плюса на минус.'],['Вторая производная x³ в точке 1.',6,'6x = 6.']],
['Ферма: в точке внутреннего локального экстремума при существовании конечной производной она равна нулю. Точки без производной и концы отрезка также проверяют при поиске глобального максимума/минимума.','Если f″>0, график чашей вверх; если f″<0 — чашей вниз. Точка перегиба требует смены выпуклости; f″=0 — лишь кандидат. Термины «выпуклая/вогнутая» сверяй с принятой в лекции конвенцией.','Вертикальная асимптота x=a возникает при бесконечном одностороннем пределе. Для наклонной y=kx+b: k=lim f(x)/x, b=lim(f(x)−kx) при x→+∞ или −∞ отдельно.','План исследования: область определения, симметрии, пересечения с осями, пределы/асимптоты, знак первой производной и экстремумы, знак второй и перегибы, согласованный эскиз графика.'])
add('primitive','Первообразная и неопределённый интеграл',M,[41],'b71b34110038','derivative',
'Интегрирование здесь — обратная задача к производной. Первообразная F для f удовлетворяет F′=f. Все первообразные на промежутке отличаются константой C, поэтому неопределённый интеграл — семейство функций.',
'Для f(x)=2x первообразная x²: её производная 2x. Но x²+7 и x²−5 тоже подходят. Записываем x²+C. Проверяй ответ дифференцированием.',
'У правила интегрирования степеней исключение: степень −1. Интеграл 1/x равен ln|x|+C на промежутке, не содержащем ноль.',
['Зачем в неопределённом интеграле прибавляют C?','Производная константы нулевая, поэтому первообразная определена с точностью до постоянной на промежутке.'],
[['F′(x)=2x, F(0)=3. Найди F(2).',7,'F=x²+3, F(2)=7.'],['Коэффициент при x³ в первообразной x².',1/3,'Увеличиваем степень до 3 и делим на 3.'],['F′(x)=3x², F(0)=1. Найди F(2).',9,'F=x³+1.'],['F′(x)=4, F(0)=−2. Найди F(3).',10,'F=4x−2.']],
['Для α≠−1: интеграл x^α равен x^(α+1)/(α+1)+C на подходящей области. Интегралы eˣ, cos x, sin x: eˣ+C, sin x+C, −cos x+C.','Линейность: интеграл af+bg равен a∫f+b∫g с учётом произвольной постоянной. Разность двух первообразных имеет нулевую производную, поэтому постоянна по теореме Лагранжа.'])
add('substitution','Замена переменной и интегрирование по частям',M,[42,55],'b71b34110038','primitive',
'Замена переменной обращает цепное правило: если рядом с выражением есть его производная, удобно назвать выражение новой буквой. Интегрирование по частям обращает правило произведения: ∫u dv = uv−∫v du.',
'В интеграле 2x·cos(x²) dx положим t=x², dt=2x dx. Получим ∫cos t dt = sin t+C = sin(x²)+C. Для ∫x eˣ dx выбираем u=x, dv=eˣdx: результат xeˣ−eˣ+C.',
'При замене в определённом интеграле меняются и пределы. Нельзя смешивать старые границы и новую переменную.',
['Как выбрать замену переменной?','Ищи внутреннее выражение, производная которого присутствует рядом с точностью до множителя.'],
[['Для t=x² чему равно dt/dx при x=3?',6,'dt/dx=2x.'],['Интеграл 2x от 0 до 2.',4,'Замена t=x²: границы 0 и 4; интеграл 1 dt равен 4.'],['Для t=3x+1 чему равно dx/dt?',1/3,'dt=3 dx.'],['Интеграл 2x(x²+1) от 0 до 1.',1.5,'t=x²+1, границы 1 и 2: (4−1)/2.']],
['В неопределённом интеграле после подстановки вернись к исходной переменной. В определённом можно сразу вычислять в новой с новыми границами.','По частям удобно брать u так, чтобы при дифференцировании оно упрощалось: x, ln x, обратные тригонометрические функции. Для определённого интеграла граничный член uv вычисляется на концах.'])
add('rational','Рациональные дроби в интегралах',M,[43,44],'b71b34110038','substitution',
'Рациональная функция — отношение многочленов. Если степень числителя не меньше степени знаменателя, сначала делят многочлены. Правильную дробь раскладывают на простейшие по множителям знаменателя.',
'1/(x(x+1)) = A/x + B/(x+1). Умножим на x(x+1): 1=A(x+1)+Bx. При x=0 получаем A=1, при x=−1 получаем B=−1. Интеграл равен ln|x|−ln|x+1|+C.',
'Для повторного множителя (x−a)² нужны оба слагаемых A/(x−a) и B/(x−a)². Для неприводимого квадратного множителя в числителе линейный многочлен.',
['Что сделать с неправильной рациональной дробью до разложения?','Выделить многочлен делением числителя на знаменатель.'],
[['В 1/(x(x+2))=A/x+B/(x+2) найди A.',.5,'При x=0: 1=2A.'],['В том же разложении найди B.',-.5,'Коэффициент x: A+B=0.'],['В 1/(x(x+4)) найди коэффициент при 1/x.',.25,'При x=0 после умножения: 1=4A.'],['В x²/(x+1)=x−1+R/(x+1) найди R.',1,'x²=(x+1)(x−1)+1.']],
['Любой действительный многочлен раскладывается в произведение линейных и неприводимых квадратных множителей. Для каждой степени линейного множителя нужен постоянный числитель; для каждой степени квадратного — линейный.','Простейшие интегралы сводятся к степеням, ln|x−a|, логарифму квадратного выражения и arctan после выделения полного квадрата. Коэффициенты находят тождеством многочленов, а не подстановкой только одного случайного x.'])
add('irrational','Иррациональные интегралы: выбор подстановки',M,[45,46,47,48],'b71b34110038','rational',
'Если под интегралом корень, цель подстановки — сделать выражение рациональным или убрать корень известным тождеством. Для корня из a²−x² помогает x=a sin t, потому что 1−sin²t=cos²t. Область и знак корня нужно учитывать.',
'Для √(9−x²) положим x=3 sin t и выберем t в [−π/2,π/2]. Тогда cos t≥0, корень равен 3 cos t, а dx=3 cos t dt. Корень исчезает, но множитель от dx остаётся.',
'√(cos²t)=|cos t|. Чтобы убрать модуль, нужно выбрать промежуток с известным знаком.',
['Зачем выбирать промежуток новой переменной в тригонометрической подстановке?','Чтобы контролировать знак корня и однозначно вернуться к исходной переменной.'],
[['В √(16−x²) при x=4 sin t чему равен множитель перед sin t?',4,'Сравним 16 с a²: a=√16=4, поэтому замена x=4 sin t.'],['Дополнить квадрат: x²+6x+13=(x+3)²+c. Найди c.',4,'(x+3)²=x²+6x+9.'],['Дополнить квадрат: x²−4x+9=(x−2)²+c.',5,'(x−2)²=x²−4x+4.'],['При t=√x и x=9 найди t.',3,'Берём неотрицательный корень.']],
['Для R(x, корень m-й степени из (αx+β)/(γx+δ)) положи корень равным t и вырази x рационально через t, если дробно-линейное выражение невырождено. Затем замени dx.','Подстановки Эйлера рационализируют √(ax²+bx+c): при a>0 берут √(...)=√a·x+t; при c>0 — √(...)=tx+√c; при действительном корне x₁ используют √(...)=t(x−x₁). Выбор зависит от области и коэффициентов.','После выделения полного квадрата применяют x=a sin t для √(a²−x²), x=a tan t для √(a²+x²), подходящую секансную/гиперболическую замену для √(x²−a²).','Для биномиального дифференциала x^m(a+bx^n)^p dx с рациональными m,n,p и n≠0 теорема Чебышёва даёт элементарную интегрируемость, когда целое хотя бы одно из чисел p, (m+1)/n, p+(m+1)/n (при невырожденных a,b). Это отдельный теоретический результат, а не правило угадывания одной замены.'])
add('trig-integrals','Тригонометрические интегралы',M,[49,50,51],'b71b34110038','substitution',
'Для произведения степеней sin и cos сначала ищут нечётную степень. Один множитель отделяют для дифференциала, остальные переводят через sin²+cos²=1. Если обе степени чётные, полезны формулы половинного угла.',
'∫sin x·cos²x dx: t=cos x, dt=−sin x dx. Получаем −∫t²dt=−t³/3+C=−cos³x/3+C. Проверка производной возвращает sin x·cos²x.',
'При замене t=cos x возникает минус. Его потеря меняет знак ответа.',
['Что отделять при нечётной степени синуса?','Один sin x для дифференциала cos x; оставшиеся чётные степени выразить через cos.'],
[['В замене t=cos x множитель перед sin x dx в dt.',-1,'dt=−sin x dx.'],['Коэффициент при cos(2x) в sin²x=(1−cos(2x))/2.',-.5,'Раскрываем деление на 2.'],['При t=tan(x/2), x=0 найди t.',0,'tan 0=0.'],['Интеграл sin x от 0 до π.',2,'[−cos x] от 0 до π = 1−(−1).']],
['Универсальная подстановка t=tan(x/2): sin x=2t/(1+t²), cos x=(1−t²)/(1+t²), dx=2dt/(1+t²). Рациональное выражение от sin и cos становится рациональным от t; точки разрыва подстановки требуют разбиения области.','Если рациональное выражение нечётно по sin, помогает t=cos x; нечётно по cos — t=sin x; инвариантно при одновременной смене знаков sin и cos — t=tan x.','Произведения sin(nx)cos(mx) переводят в сумму: 2sin A cos B=sin(A+B)+sin(A−B). Это позволяет интегрировать каждое слагаемое отдельно.'])
add('definite','Определённый интеграл и Ньютон–Лейбниц',M,[52,53,54],'05f9eef3ef5c','primitive',
'Определённый интеграл — предел сумм маленьких вкладов на отрезке. Для положительной функции это площадь под графиком; участки ниже оси дают отрицательный вклад. Если известна первообразная F, интеграл от a до b равен F(b)−F(a).',
'Интеграл 2x от 1 до 3: первообразная x². Вычислим 3²−1²=8. Ответ — число, поэтому +C не добавляем.',
'Интеграл — знаковая величина. Геометрическая площадь всегда неотрицательна и может требовать разбиения.',
['Как вычислить определённый интеграл через первообразную?','Значение первообразной на верхней границе минус значение на нижней.'],
[['Интеграл 2x от 0 до 3.',9,'[x²]₀³=9.'],['Интеграл 3 от 2 до 5.',9,'Высота 3, длина отрезка 3.'],['Интеграл x от −1 до 1.',0,'Нечётная функция на симметричном отрезке.'],['Интеграл x² от 0 до 3.',9,'[x³/3]₀³=27/3.']],
['Суммы Римана: сумма f(ξᵢ)Δxᵢ для разбиения отрезка и выбранных точек. Интегрируемость означает общий предел при стремлении максимальной длины частей к нулю, независимо от выбора точек.','Нижние суммы Дарбу используют инфимумы на частях, верхние — супремумы. Ограниченная функция интегрируема тогда и только тогда, когда разность верхних и нижних сумм можно сделать сколь угодно малой. Непрерывные, монотонные и кусочно-непрерывные функции на отрезке интегрируемы.','Свойства: линейность, аддитивность по отрезку, сохранение неравенств, смена знака при перестановке границ. Для непрерывной f среднее интегральное значение равно f(c) в некоторой точке: ∫f=f(c)(b−a).','Функция F(x)=∫ от a до x f(t)dt имеет производную f(x), если f непрерывна. Идея: разностное отношение — среднее значение f на малом отрезке. Ньютон–Лейбниц следует из того, что любые две первообразные отличаются постоянной.'])
add('integral-geometry','Площади, длины и объёмы',M,[56,57,58,59,60],'05f9eef3ef5c','definite',
'Для площади между графиками интегрируют «верхняя функция минус нижняя» на промежутках, где их порядок известен. Для тела вращения вокруг оси x используют площади дисков: π·радиус², затем суммируют интегралом.',
'Между y=2x и y=0 на [0,2] площадь равна ∫2x dx=4. При вращении y=2 вокруг оси x на [0,3] получаем цилиндр: объём ∫4π dx=12π.',
'В объёме радиус возводится в квадрат; в площади поверхности вращения радиус входит в первой степени.',
['Как найти площадь между двумя графиками?','Разбить область по точкам пересечения и интегрировать верхнюю функцию минус нижнюю на каждом участке.'],
[['Площадь под y=x на [0,4].',8,'Интеграл x: 4²/2=8.'],['V/π для вращения y=3 на [0,2] вокруг оси x.',18,'Интеграл 3² dx = 9×2.'],['Площадь между y=3 и y=1 на [0,5].',10,'Разность высот 2, длина 5.'],['Длина отрезка графика y=0 на [1,6].',5,'Горизонтальный отрезок длины 5.']],
['В полярных координатах площадь сектора: половина интеграла r(φ)² по углу. Длина явного графика: ∫√(1+(y′)²) dx; параметрической кривой: ∫√((x′)²+(y′)²) dt; полярной: ∫√(r²+(r′)²) dφ при гладкости.', 'Объём тела по сечениям: ∫S(x)dx. Для вращения области между внешним R и внутренним r вокруг оси x: π∫(R²−r²)dx. Площадь поверхности вращения гладкого графика: 2π∫|y|√(1+(y′)²)dx.'])
add('matrix-operations','Операции с матрицами',L,[1],'9b45082ee927','matrix',
'Складывают матрицы одинакового размера по соответствующим элементам. Для произведения A·B число столбцов A должно равняться числу строк B. Элемент результата — сумма произведений элементов строки A и столбца B.',
'Для $A = [[1,2],[3,4]]$ и $B = [[2,0],[1,3]]$ элемент (AB)₁₁ равен 1·2+2·1=4, элемент (AB)₁₂ равен 1·0+2·3=6. Проделав то же со второй строкой, получаем $[[4,6],[10,12]]$.',
'Умножение матриц обычно не перестановочно: AB и BA могут различаться или одно из произведений вообще не определено.',
['Как найти элемент произведения матриц?','Умножить попарно элементы нужной строки первой матрицы и столбца второй, затем сложить.'],
[['A=[[1,2],[3,4]], B=[[2,0],[1,3]]. Найди (AB)₂₁.',10,'3·2+4·1=10.'],['A=[[1,2],[3,4]]. Найди (A+A)₁₂.',4,'2+2=4.'],['Строка [2,3], столбец [4,5]. Их произведение?',23,'2·4+3·5=23.'],['A имеет размер 2×3, B — 3×4. Сколько столбцов в AB?',4,'Результат имеет размер 2×4.']],
['Нулевая матрица содержит только нули. Единичная квадратная матрица имеет единицы на главной диагонали и нули вне неё, AI=IA=A. Диагональная имеет нули вне диагонали, треугольная — по одну сторону от неё.','Транспонирование меняет строки со столбцами: (AB)ᵀ=BᵀAᵀ. Ассоциативность и дистрибутивность работают, но перестановка сомножителей требует отдельного обоснования.'])
add('determinant','Определитель: когда направления схлопываются',L,[3,4],'9b45082ee927','matrix-operations',
'Определитель — число для квадратной матрицы. Для матрицы 2×2 с первой строкой (a,b), второй (c,d) это ad−bc. Нулевой определитель означает линейную зависимость столбцов и отсутствие обратной матрицы.',
'У $[[2,1],[3,4]]$ определитель 2·4−1·3=5. Если поменять строки местами, получим −5. Если к одной строке прибавить кратную другой, определитель не изменится.',
'Определитель есть только у квадратных матриц. Нельзя умножить все элементы 2×2 на k и ожидать увеличения определителя только в k раз: получится k².',
['Что происходит с определителем при перестановке двух строк?','Он меняет знак.'],
[['Определитель [[1,2],[3,4]].',-2,'1·4−2·3=−2.'],['Определитель [[3,0],[0,5]].',15,'Для диагональной матрицы — произведение диагонали.'],['Определитель [[2,4],[1,2]].',0,'4−4=0, строки зависимы.'],['Определитель был 7, две строки поменяли местами. Новый?',-7,'Одна перестановка меняет знак.']],
['Минор Mᵢⱼ — определитель после удаления строки i и столбца j. Алгебраическое дополнение Aᵢⱼ=(−1)^(i+j)Mᵢⱼ. Разложение по любой строке i: det A=Σ aᵢⱼAᵢⱼ; аналогично по столбцу. Независимость выбора следует из определения определителя через перестановки.','Определитель транспонированной матрицы тот же. Вынесение множителя из одной строки выносит его из определителя; две одинаковые или зависимые строки дают ноль. det(AB)=det A·det B. Для треугольной матрицы det — произведение диагональных элементов.'])
add('gauss','Метод Гаусса и ранг',L,[2,5,8],'d22f9eac3f1d','matrix-operations',
'Метод Гаусса последовательно убирает неизвестные из нижних строк. Можно менять уравнения местами, умножать уравнение на ненулевое число и прибавлять кратное другого. Ранг — количество независимых направлений, в ступенчатой форме равное числу ненулевых строк.',
'Система x+y=3, 2x+3y=8. Из второго уравнения вычтем удвоенное первое: y=2. Подставим в первое: x=1. У ведущих элементов два независимых столбца, ранг равен 2.',
'Преобразуя расширенную матрицу, меняй и правую часть. Строка 0=5 означает несовместность, а 0=0 — лишнее уравнение.',
['Как определить ранг по ступенчатой матрице?','Посчитать её ненулевые строки (ведущие элементы).'],
[['Ранг [[1,2],[2,4]].',1,'Вторая строка вдвое больше первой.'],['x+y=5, x−y=1. Найди x.',3,'Сложение уравнений: 2x=6.'],['Ранг [[1,0,2],[0,1,3]].',2,'Две строки с разными ведущими элементами.'],['x+y=7, 2x+3y=18. Найди y.',4,'Вычтем удвоенное первое: y=4.']],
['Ступенчатая форма: нулевые строки внизу, каждый следующий ведущий элемент правее предыдущего, под ведущими — нули. В приведённой ступенчатой форме ведущие элементы равны 1 и являются единственными ненулевыми в своих столбцах.','Элементарная матрица получается одной операцией над строками единичной; умножение слева выполняет соответствующую операцию над строками другой матрицы.','Теорема о базисном миноре: строки/столбцы, содержащие ненулевой минор максимального порядка r, независимы; остальные выражаются через них. Поэтому ранг равен максимальному порядку ненулевого минора.','Кронекер–Капелли: система совместна тогда и только тогда, когда ранги основной и расширенной матриц равны. Если общий ранг равен числу неизвестных, решение единственное; если меньше — есть свободные параметры.'])
add('inverse','Обратная матрица и Крамер',L,[6,7],'9b45082ee927','determinant',
'Обратная матрица отменяет действие исходной: AA⁻¹=I. Для квадратной матрицы она существует ровно при ненулевом определителе. Тогда Ax=b решается как x=A⁻¹b.',
'Для диагональной $[[2,0],[0,4]]$ обратная $[[0.5,0],[0,0.25]]$. Произведение даёт единичную. Для общей 2×2 меняют местами диагональные элементы, меняют знаки остальных и делят на определитель.',
'При нулевом определителе нельзя применять формулы обратной матрицы и Крамера с делением на определитель.',
['Когда квадратная матрица обратима?','Когда её определитель не равен нулю (эквивалентно полному рангу).'],
[['Первый диагональный элемент обратной к [[4,0],[0,2]].',.25,'Обратная к 4 — 1/4.'],['x+y=5, x−y=1. Найди y.',2,'Вычитание даёт 2y=4.'],['Определитель обратной, если det A=5.',.2,'det(A⁻¹)=1/det A.'],['Второй диагональный элемент обратной к [[3,0],[0,5]].',.2,'Для диагональной матрицы каждый ненулевой диагональный элемент заменяется обратным: 1/5 = 0,2.']],
['Метод Гаусса для обратной: приписать справа I и преобразовать [A|I] в [I|A⁻¹]. Присоединённая матрица — транспонированная матрица алгебраических дополнений; A⁻¹=adj(A)/det A.','Крамер: для квадратной системы с det A≠0 неизвестное xᵢ=det Aᵢ/det A, где Aᵢ получается заменой i-го столбца на правую часть. Свойства обратной: (AB)⁻¹=B⁻¹A⁻¹, (Aᵀ)⁻¹=(A⁻¹)ᵀ.'])
add('homogeneous','Свободные переменные и общее решение',L,[9,10],'d22f9eac3f1d','gauss',
'Однородная система Ax=0 всегда имеет нулевое решение. Ненулевые решения появляются, если независимых условий меньше, чем неизвестных. Свободные переменные можно выбирать, остальные выражаются через них.',
'У x+y+z=0 возьмём y=s, z=t. Тогда x=−s−t, решение s(−1,1,0)+t(−1,0,1). Два независимых вектора образуют фундаментальную систему решений.',
'Для неоднородной системы сумма двух решений обычно не решение. Её решения — частное решение плюс решения однородной.',
['Сколько параметров у совместной системы из n неизвестных ранга r?','n−r свободных параметров.'],
[['Число свободных параметров при n=5, r=3.',2,'5−3=2.'],['Для x+y=0 при y=4 найди x.',-4,'x=−y.'],['Размерность пространства решений Ax=0 при n=4, r=1.',3,'4−1=3.'],['x+y=3 при y=2: найди x.',1,'Частное решение можно получить прямой подстановкой.']],
['Решения однородной системы замкнуты относительно сложения и умножения на скаляр. Ненулевое решение существует тогда и только тогда, когда r<n. Фундаментальная система — базис ядра, содержит n−r векторов.','Если x₀ решает Ax=b, то каждое решение имеет вид x₀+z, где Az=0. Доказательство: A(x−x₀)=b−b=0; обратно A(x₀+z)=b. Фундаментальная матрица имеет в столбцах векторы фундаментальной системы.'])
add('vectors','Векторы, координаты и базис',L,[11,25,26],'400d4c3f1eda','gauss',
'Вектор описывает направление и величину; координаты — числа в выбранном базисе. Базис — независимый набор, через который выражается любой вектор пространства. Размерность — количество векторов в базисе.',
'В обычном базисе плоскости (1,0),(0,1) вектор (3,2) равен 3(1,0)+2(0,1). В базисе (2,0),(0,1) тот же вектор имеет координаты (1,5; 2), то есть коэффициенты 1,5 и 2.',
'Сам вектор и его координаты — разные вещи: координаты зависят от выбора базиса.',
['Какие два свойства определяют базис?','Линейная независимость и возможность выразить любой вектор пространства.'],
[['Размерность пространства обычных векторов плоскости.',2,'Базис состоит из двух векторов.'],['A=(1,2), B=(4,6). Первая координата AB.',3,'B−A=(3,4).'],['Длина вектора (3,4).',5,'Корень из 9+16.'],['Первая координата середины отрезка от (2,0) до (8,4).',5,'(2+8)/2=5.']],
['Линейное пространство задаётся сложением и умножением на скаляр с аксиомами. Подпространство непусто и замкнуто относительно линейных комбинаций. Линейная оболочка — множество всех линейных комбинаций заданных векторов.','Независимость: нулевая линейная комбинация возможна только при всех нулевых коэффициентах. Для n векторов Rⁿ это равносильно ненулевому определителю матрицы их столбцов.','Аффинная система — начало и базис; декартова — ортонормированный базис. Вектор AB=B−A. Точка внутреннего деления AB в отношении m:n равна (nA+mB)/(m+n).'])
add('dot','Скалярное произведение и матрица Грама',L,[12,13,28],'3ebb041a46d0','vectors',
'Скалярное произведение двух векторов даёт число. В ортонормированных координатах перемножают соответствующие координаты и складывают. Геометрически это произведение длин на cos угла. Нулевое произведение ненулевых векторов означает перпендикулярность.',
'Для a=(1,2), b=(3,4) произведение 1·3+2·4=11. Квадрат длины a равен a·a=5. Для (1,0) и (0,1) произведение ноль: угол прямой.',
'Простая сумма произведений координат верна в ортонормированном базисе. В произвольном нужна матрица Грама.',
['Как проверить перпендикулярность двух ненулевых векторов?','Их скалярное произведение должно быть нулевым.'],
[['(2,3)·(4,−1).',5,'8−3=5.'],['Квадрат длины (1,2,2).',9,'1+4+4=9.'],['(1,1)·(1,−1).',0,'1−1=0.'],['Длина вектора (0,3,4).',5,'√25=5.']],
['Евклидово пространство — действительное линейное пространство со скалярным произведением: симметричным, билинейным и положительно определённым. Матрица Грама Gᵢⱼ=(eᵢ,eⱼ), произведение в координатах xᵀGy.','Коши–Буняковский–Шварц: |(x,y)|≤||x||·||y||. Доказательство: квадрат нормы x−ty неотрицателен для всех t; дискриминант соответствующего квадратного трёхчлена неположителен. Отсюда следует неравенство треугольника.','В ортонормированном базисе G=I. Матрица Грама независимых векторов положительно определена; зависимых — вырождена. cos угла равен скалярному произведению, делённому на произведение ненулевых длин.'])
add('orthogonal','Проекция, Грам–Шмидт и смена базиса',L,[14,15,16],'400d4c3f1eda','dot',
'Проекция вектора на направление — его часть вдоль этого направления. Для ненулевого u проекция v равна u·(v·u)/(u·u). Вычитание проекции оставляет перпендикулярную часть. На этом построена ортогонализация Грама–Шмидта.',
'Возьмём u=(1,0), v=(2,3). Проекция v на u — (2,0). Остаток (0,3) перпендикулярен u. Разделим каждый вектор на его длину — получим ортонормированный базис.',
'В формуле проекции нужен квадрат длины u в знаменателе. Делить только на длину можно для скалярной компоненты, а не этой векторной формулы.',
['Как построить перпендикулярный остаток в методе Грама–Шмидта?','Вычесть проекции на все ранее построенные ортогональные направления.'],
[['Первая координата проекции (3,4) на ось x.',3,'Проекция (3,0).'],['Квадрат нормы вектора с координатами (2,3) в ортонормированном базисе.',13,'По Парсевалю: 4+9.'],['В базисе (2,0),(0,1) первая координата вектора (6,5).',3,'6=3×2.'],['Квадрат длины остатка (2,3) после проекции на (1,0).',9,'Остаток (0,3).']],
['В ортогональном базисе векторы попарно перпендикулярны; в ортонормированном дополнительно имеют длину 1. Равенство Парсеваля: квадрат нормы — сумма квадратов координат в ортонормированном базисе.','Грам–Шмидт: из очередного исходного вектора вычесть проекции на все ранее построенные ортогональные векторы, затем при необходимости нормировать. Для независимого исходного набора остатки ненулевые.','Ортогональное дополнение U состоит из векторов, перпендикулярных всем векторам U. В конечномерном евклидовом пространстве V=U⊕U⊥.','Если столбцы C — новые базисные векторы в старых координатах, то x_стар=C x_нов; следовательно x_нов=C⁻¹x_стар. Всегда проговаривай направление перехода.'])
add('maps','Линейные отображения',L,[17,18,19,20],'864b448d1572','vectors',
'Линейное отображение сохраняет сложение и умножение на число: T(au+bv)=aT(u)+bT(v). Оно обязательно переводит нулевой вектор в нулевой. Матрица собирается из образов базисных векторов в столбцах.',
'T(x,y)=(2x,3y) имеет матрицу $[[2,0],[0,3]]$. Столбцы — образы (1,0) и (0,1). Образ (4,5) равен (8,15). Перенос T(x,y)=(x+1,y) не линейный: ноль переходит в (1,0).',
'«Сдвиг» в лекции означает сдвиговую деформацию (shear), например (x+ky,y), а не перенос всех точек на фиксированный ненулевой вектор.',
['Как получить столбцы матрицы линейного отображения?','Применить отображение к каждому базисному вектору и записать координаты образов.'],
[['T(x,y)=(2x,3y). Первая координата T(4,5).',8,'Подставляем x=4 в первую компоненту отображения: 2×4 = 8.'],['T(x,y)=(x+2y,y). Первая координата T(1,3).',7,'Подставляем x=1, y=3: x+2y = 1+6 = 7.'],['На сколько умножается x при композиции масштабов 2 и 3?',6,'Матрицы умножаются, 2×3=6.'],['Размерность ядра тождественного отображения R².',0,'В ноль переходит только нулевой вектор.']],
['Инъективность означает разные образы разных входов, для линейного отображения это равносильно нулевому ядру. Сюръективность означает, что образ равен всему целевому пространству. Биективное линейное отображение — изоморфизм.','Матрица тождественного отображения I; растяжения — диагональная; поворота плоскости — строки (cos φ, −sin φ), (sin φ, cos φ). Сдвиговая деформация имеет, например, матрицу [[1,k],[0,1]].','Композиция соответствует произведению матриц в порядке применения справа налево. Для одного преобразования при смене базиса A_нов=C⁻¹A_стар C; такие матрицы подобны. Для разных базисов входа и выхода используются две разные матрицы перехода.'])
add('eigen','Собственные значения и диагонализация',L,[21,22,23,24],'864b448d1572','inverse',
'Собственный вектор — ненулевой вектор, направление которого преобразование сохраняет, возможно меняя знак. Av=λv; число λ называется собственным значением. Чтобы найти λ, решают det(A−λI)=0, затем для каждого λ решают однородную систему.',
'У $[[2,0],[0,3]]$ собственные значения 2 и 3. Для λ=2 подходят ненулевые векторы оси x, для λ=3 — оси y. Матрица уже диагональна в базисе собственных векторов.',
'Нулевой вектор не считается собственным. Кратность корня характеристического многочлена не гарантирует столько же независимых собственных векторов.',
['Какое уравнение находят для собственных значений?','det(A−λI)=0. Затем для каждого корня находят ненулевые решения (A−λI)v=0.'],
[['Большое собственное значение диагональной [[2,0],[0,5]].',5,'Диагональные элементы — собственные значения.'],['Сумма собственных значений [[2,1],[0,3]].',5,'Это след: 2+3.'],['Произведение собственных значений [[2,1],[0,3]].',6,'Это определитель: 2×3.'],['A=[[4,0],[0,7]], v=(1,0). Найди λ в Av=λv.',4,'Av=(4,0).']],
['Характеристический многочлен det(A−λI) не зависит от базиса, поскольку при подобии определители множителей C и C⁻¹ сокращаются. След и определитель — сумма и произведение собственных значений с алгебраическими кратностями.','Собственные векторы разных собственных значений линейно независимы. Если имеется базис из собственных векторов, матрица в нём диагональна. Обратно диагонализируемость требует такого базиса.','Для действительной симметричной матрицы существует ортонормированный базис собственных векторов и все собственные значения действительны. У поворота плоскости на угол, не кратный π, действительных собственных векторов нет.'])
add('cross','Векторное и смешанное произведения',L,[29,30,31],'3ebb041a46d0','dot',
'В R³ векторное произведение a×b перпендикулярно обоим векторам, его длина — площадь параллелограмма. Ориентация задаётся правилом правой руки. Смешанное произведение (a×b)·c — ориентированный объём параллелепипеда.',
'Для a=(1,0,0), b=(0,1,0) получаем a×b=(0,0,1). Если c=(0,0,3), смешанное произведение равно 3. Объём тетраэдра с этими рёбрами равен |3|/6=0,5.',
'Перестановка двух векторов меняет знак произведения. Геометрический объём берётся по модулю.',
['Как связан объём параллелепипеда со смешанным произведением?','Объём равен модулю смешанного произведения трёх рёбер из одной вершины.'],
[['Площадь параллелограмма на (2,0,0) и (0,3,0).',6,'Векторное произведение (0,0,6), длина 6.'],['Объём параллелепипеда на (2,0,0),(0,3,0),(0,0,4).',24,'Определитель диагональной матрицы: 2×3×4.'],['Объём тетраэдра с теми же тремя рёбрами.',4,'24/6=4.'],['Смешанное произведение трёх компланарных векторов.',0,'Объём равен нулю.']],
['Координаты a×b: (a₂b₃−a₃b₂, a₃b₁−a₁b₃, a₁b₂−a₂b₁). Векторы коллинеарны тогда и только тогда, когда их векторное произведение равно нулю.','Смешанное произведение равно определителю координат трёх векторов; его нуль равносилен компланарности. Площадь треугольника — половина длины a×b, объём тетраэдра — шестая часть модуля смешанного произведения.'])
add('coordinates','Полярные координаты и поверхности',L,[27,32,33],'4bdc3c9c217d','trigonometry',
'Точку плоскости можно задавать расстоянием r от начала и углом φ: x=r cos φ, y=r sin φ. Это полярные координаты. В пространстве цилиндрические добавляют высоту z.',
'При r=2 и φ=π/2 получаем x=0, y=2. Уравнение x²+y²=4 в пространстве не ограничивает z: это цилиндр, а не окружность. Окружность получится, если добавить z=0.',
'Одно и то же уравнение может описывать разные объекты в плоскости и в пространстве.',
['Почему x²+y²=4 в пространстве задаёт цилиндр?','Координата z свободна; одна и та же окружность повторяется на любой высоте.'],
[['r=3, φ=0. Найди x.',3,'3 cos 0=3.'],['Для точки (3,4) найди r.',5,'√(9+16)=5.'],['Радиус цилиндра x²+y²=9.',3,'r²=9.'],['r=4, φ=π/2. Найди y.',4,'4 sin(π/2)=4.']],
['Сферические координаты в конвенции с полярным углом θ от оси z: x=ρ sin θ cos φ, y=ρ sin θ sin φ, z=ρ cos θ. В лекциях могут использовать другой отсчёт углов, поэтому сверяй обозначения.','Поверхность F(x,y,z)=0 алгебраическая, если F — многочлен. Кривая в пространстве может задаваться пересечением двух поверхностей или параметрически.','Цилиндрическая поверхность состоит из параллельных образующих, коническая — из прямых через одну вершину. Поверхность вращения получают вращением кривой вокруг оси; радиус до оси заменяется соответствующим корнем суммы квадратов.'])
add('planes','Плоскости и расстояния',L,[34,35,36],'4bdc3c9c217d','dot',
'Плоскость Ax+By+Cz+D=0 имеет нормаль (A,B,C), перпендикулярную ей. Коэффициенты A,B,C не все нулевые. Через точку r₀ плоскость с нормалью n задаётся условием n·(r−r₀)=0.',
'Плоскость через (1,0,0) с нормалью (2,0,0): 2(x−1)=0, то есть x=1. Расстояние от (4,2,3) до неё равно 3.',
'Нормаль плоскости — не вектор, лежащий в ней. Для расстояния числитель берётся по модулю.',
['Какой вектор является нормалью плоскости Ax+By+Cz+D=0?','(A,B,C), если он ненулевой.'],
[['Расстояние от (5,0,0) до x=2.',3,'|5−2|=3.'],['Плоскость 2x+3y+4z−1=0. Третья координата нормали.',4,'Коэффициент при z.'],['Расстояние от (0,0,0) до 3x+4y−10=0.',2,'10/√(9+16)=2.'],['Какое D у плоскости x+y+z+D=0 через (1,2,3)?',-6,'1+2+3+D=0.']],
['Расстояние от (x₀,y₀,z₀) до плоскости: |Ax₀+By₀+Cz₀+D|/√(A²+B²+C²). Угол между плоскостями находят по нормалям; для меньшего угла используют модуль косинуса.','Параллельность плоскостей определяется коллинеарностью нормалей; перпендикулярность — нулевым скалярным произведением нормалей.','Для плоскости через три неколлинеарные точки возьми два вектора между ними и их векторное произведение как нормаль. Параметрическая векторная запись: r=r₀+su+tv с независимыми u,v. Форма в отрезках x/a+y/b+z/c=1 применима при ненулевых конечных пересечениях с осями.'])
add('lines','Прямые в пространстве и углы',L,[37,38],'4bdc3c9c217d','planes',
'Прямая задаётся точкой r₀ и ненулевым направлением v: r=r₀+tv. Параметр t пробегает действительные числа. Угол между прямыми находят по их направлениям, между прямой и плоскостью — через нормаль плоскости.',
'Прямая через (1,2,3) с направлением (2,0,−1): x=1+2t, y=2, z=3−t. При t=2 получаем (5,2,1). Направление (2,0,−1) не означает, что прямая проходит через эту точку.',
'Нулевой компонент направления не разрешает делить на него в каноническом уравнении. Вместо дроби соответствующая координата постоянна.',
['Какие данные задают прямую в пространстве?','Одна точка и ненулевой направляющий вектор.'],
[['x=1+2t, y=2, z=3−t. Найди x при t=3.',7,'1+2×3=7.'],['Та же прямая: z при t=2.',1,'3−2=1.'],['Скалярное произведение направлений (1,0,0),(0,1,0).',0,'Направления перпендикулярны.'],['Сколько независимых плоскостей обычно нужно для задания прямой их пересечением?',2,'Две непараллельные плоскости пересекаются по прямой.']],
['Если все компоненты v ненулевые, каноническая форма: (x−x₀)/v₁=(y−y₀)/v₂=(z−z₀)/v₃. Прямая как пересечение плоскостей имеет направление n₁×n₂ при независимых нормалях.','Для меньшего угла между прямыми cos α=|u·v|/(||u||||v||). Между прямой v и плоскостью нормали n: sin α=|v·n|/(||v||||n||). Не перепутай синус с косинусом.'])
add('conics','Эллипс, гипербола и парабола',L,[39,40,41],'4bdc3c9c217d','powers',
'Кривые второго порядка задаются квадратными уравнениями. Эллипс ограничен; гипербола имеет две ветви; парабола равноудалена от фокуса и директрисы. Знаки и нормировка уравнения помогают отличить формы.',
'У x²/9+y²/4=1 полуоси 3 и 2: это эллипс. У x²/9−y²/4=1 это гипербола, асимптоты y=±(2/3)x. У y²=4x парабола формы y²=2px имеет p=2.',
'Под квадратами полуосей стоят 9 и 4, сами полуоси равны 3 и 2. Для параболы в разных книгах используют 2p или 4p — называй принятую форму.',
['Чем по каноническому уравнению отличаются эллипс и гипербола?','У эллипса сумма положительных квадратных членов равна 1, у гиперболы — разность.'],
[['Большая полуось x²/25+y²/9=1.',5,'√25=5.'],['Для этого эллипса фокусное расстояние c от центра.',4,'c²=25−9=16.'],['В y²=6x при форме y²=2px найди p.',3,'2p=6.'],['Меньшая полуось x²/16+y²/4=1.',2,'√4=2.']],
['Эллипс — точки с суммой расстояний до двух фокусов 2a; c²=a²−b², эксцентриситет e=c/a<1. Для a>b директрисы x=±a/e. Окружность — предельный случай c=0, конечных директрис нет.','Гипербола — модуль разности расстояний до фокусов 2a; c²=a²+b², e=c/a>1, директрисы x=±a/e, асимптоты y=±(b/a)x при поперечной оси x.','Для y²=2px при p>0 фокус (p/2,0), директриса x=−p/2. Расстояние до фокуса равно расстоянию до директрисы; возведение этого равенства в квадрат даёт уравнение параболы.'])
add('forms','Линейные, билинейные и квадратичные формы',L,[42,43,44,45],'c4b7eb6ae73c','eigen',
'Линейная форма переводит вектор в число линейно. Билинейная форма зависит от двух векторов и линейна по каждому. Квадратичная форма получается подстановкой одного вектора дважды: q(x)=xᵀAx, где можно взять симметричную A.',
'Для q(x,y)=2x²+4xy+3y² симметричная матрица $[[2,2],[2,3]]$: смешанный член появляется дважды, поэтому вне диагонали стоят 2, а не 4. Главные угловые миноры 2 и 6−4=2 положительны: форма положительно определена.',
'При составлении симметричной матрицы смешанный коэффициент делят на 2. Проверка только диагональных элементов не заменяет критерий Сильвестра.',
['Как разместить коэффициент при xy в симметричной матрице формы?','Половину коэффициента поставить в каждую из двух симметричных внедиагональных позиций.'],
[['В q=x²+6xy+2y² найди a₁₂ симметричной матрицы.',3,'6/2=3.'],['Определитель матрицы [[2,1],[1,2]].',3,'4−1=3.'],['q=2x²+3y². Найди q(1,2).',14,'2+12=14.'],['Первый угловой минор [[3,1],[1,2]].',3,'Это верхний левый элемент.']],
['Линейная форма l(x)=aᵀx. При x=Cx_нов коэффициенты становятся Cᵀa. Билинейная форма B(x,y)=xᵀAy, при общей смене базиса её матрица становится CᵀAC — это конгруэнция, не подобие.','Симметричная форма имеет Aᵀ=A, кососимметричная Aᵀ=−A. Любая матрица единственным образом разлагается в (A+Aᵀ)/2+(A−Aᵀ)/2. Кососимметричная часть даёт ноль при одинаковых аргументах.','Критерий Сильвестра для действительной симметричной матрицы: положительная определённость равносильна положительности всех ведущих главных миноров. Для отрицательной определённости знаки чередуются начиная с минуса. Для полуопределённости этот простой тест недостаточен.'])
add('quadrics','Приведение и классификация квадрик',L,[46,47,48,49,50],'fdacd963b5f0','forms',
'Уравнение второй степени можно упростить поворотом осей и переносом начала. Поворот убирает смешанные квадратичные члены, перенос — подходящие линейные. По оставшимся знакам и свободным переменным распознают поверхность.',
'У x²+y²+z²−2x−4y−6z+10=0 выделим квадраты: (x−1)²+(y−2)²+(z−3)²=4. Это сфера с центром (1,2,3) и радиусом 2.',
'Отсутствие одной переменной означает свободное направление и часто цилиндр. Нельзя классифицировать поверхность только по наличию слова «квадрат».',
['Как убрать смешанные квадратичные члены у симметричной формы?','Перейти к ортонормированному базису собственных векторов её матрицы.'],
[['Радиус x²+y²+z²=16.',4,'Корень из 16.'],['x²+y²−2x−4y=4. Координата x центра.',1,'(x−1)²+(y−2)²=9.'],['Число отрицательных квадратов в x²+y²−z²=1.',1,'Только −z².'],['У x²/9+y²/4+z²=1 полуось вдоль x.',3,'Корень из 9.']],
['Общий вид: xᵀAx+2bᵀx+c=0 с симметричной A. Ортогональная диагонализация A убирает смешанные члены. Для ненулевых собственных значений выделяют полные квадраты; вдоль нулевых направлений могут остаться линейные члены.','Эллипсоид: x²/a²+y²/b²+z²/c²=1. Однополостный гиперболоид: два плюса, один минус, справа 1. Двуполостный: один плюс, два минуса, справа 1. Конус: два плюса, один минус, справа 0.','Эллиптический параболоид: z=x²/a²+y²/b². Гиперболический: z=x²/a²−y²/b², седловая форма.','Цилиндры получаются, когда одна координата свободна: эллиптический x²/a²+y²/b²=1, гиперболический x²/a²−y²/b²=1, параболический y²=2px.','Вырожденные случаи не пропускай: уравнение может задавать точку, пустое множество, пару плоскостей/прямых. Для кривых плоскости применяют те же шаги диагонализации и переноса в двух координатах.'])
